// Command gen writes the two generated files of the bindings, the parts that
// reflection cannot find at run time because Go keeps no list of them:
//
//   - enums_gen.go: for every enumerated type of the bound Go packages — a
//     named type with a block of constants, such as stats.Alternative or
//     optimize.Method — the Ruby symbols that name its values;
//   - special_gen.go: every exported function of go-numerics/special, by
//     name, which the Special module then binds by its signature.
//
// Run it from the module root with `go generate` (or `go run ./internal/gen`);
// TestGeneratedFilesAreCurrent fails when either is out of date.
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"unicode"
)

// packages are the bound packages, by import path and the name the generated
// file imports them under.
var packages = []struct{ path, name string }{
	{"github.com/go-statistics/stats", "stats"},
	{"github.com/go-numerics/optimize", "optimize"},
	{"github.com/go-numerics/integrate", "integrate"},
}

type constant struct{ name string }

// exit is os.Exit, a seam for tests.
var exit = os.Exit

func main() {
	dir := "."
	if len(os.Args) > 1 {
		dir = os.Args[1]
	}
	if err := writeAll(dir, moduleDir); err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		exit(1)
	}
}

// writeAll writes both files into dir.
func writeAll(dir string, mod func(string) (string, error)) error {
	enums, err := generate(mod)
	if err != nil {
		return err
	}
	funcs, err := generateSpecial(mod)
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, "enums_gen.go"), enums, 0o644); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "special_gen.go"), funcs, 0o644)
}

// generateSpecial returns the source of special_gen.go.
func generateSpecial(mod func(string) (string, error)) ([]byte, error) {
	d, err := mod("github.com/go-numerics/special")
	if err != nil {
		return nil, err
	}
	names, err := funcs(d)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/gen; DO NOT EDIT.\n\npackage ruby\n\nimport \"github.com/go-numerics/special\"\n\n")
	b.WriteString("// specialFuncs are the exported functions of go-numerics/special.\nvar specialFuncs = []namedFunc{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t{%q, special.%s},\n", n, n)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// funcs lists the exported, non-generic top-level functions of the package in
// dir, sorted.
func funcs(dir string) ([]string, error) {
	files, err := goFiles(dir)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	var out []string
	for _, f := range files {
		file, err := parser.ParseFile(fset, f, nil, 0)
		if err != nil {
			return nil, err
		}
		for _, d := range file.Decls {
			if fd, ok := d.(*ast.FuncDecl); ok && fd.Recv == nil && fd.Name.IsExported() && fd.Type.TypeParams == nil {
				out = append(out, fd.Name.Name)
			}
		}
	}
	sort.Strings(out)
	return out, nil
}

// goFiles are the non-test Go files of dir, sorted.
func goFiles(dir string) ([]string, error) {
	all, _ := filepath.Glob(filepath.Join(dir, "*.go"))
	var files []string
	for _, f := range all {
		if !strings.HasSuffix(f, "_test.go") {
			files = append(files, f)
		}
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("no Go files in %s", dir)
	}
	sort.Strings(files)
	return files, nil
}

// moduleDir finds a module's source in the module cache; a seam for tests.
var moduleDir = func(path string) (string, error) {
	cmd := exec.Command("go", "list", "-m", "-f", "{{.Dir}}", path)
	cmd.Env = append(os.Environ(), "GOWORK=off")
	b, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("go list -m %s: %v", path, err)
	}
	return strings.TrimSpace(string(b)), nil
}

// generate returns the formatted source of enums_gen.go.
func generate(dir func(string) (string, error)) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/gen; DO NOT EDIT.\n\npackage ruby\n\nimport (\n\t\"reflect\"\n\n")
	for _, p := range packages {
		fmt.Fprintf(&b, "\t%q\n", p.path)
	}
	b.WriteString(")\n\n// enumTable lists, for each enumerated Go type, its values and the Ruby\n// symbols that name them.\nvar enumTable = map[reflect.Type][]enumValue{\n")
	for _, p := range packages {
		d, err := dir(p.path)
		if err != nil {
			return nil, err
		}
		groups, err := enums(d)
		if err != nil {
			return nil, err
		}
		types := make([]string, 0, len(groups))
		for t := range groups {
			types = append(types, t)
		}
		sort.Strings(types)
		for _, t := range types {
			consts := groups[t]
			fmt.Fprintf(&b, "\treflect.TypeFor[%s.%s](): {\n", p.name, t)
			names := make([]string, len(consts))
			for i, c := range consts {
				names[i] = c.name
			}
			strip := commonPrefix(names)
			for _, c := range consts {
				fmt.Fprintf(&b, "\t\t{%q, %s.%s},\n", snake(c.name[len(strip):]), p.name, c.name)
			}
			b.WriteString("\t},\n")
		}
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// enums returns the exported constants of each exported named type declared in
// the package in dir, in declaration order. A constant without a type of its
// own inherits the previous one's in its block, as iota constants do.
func enums(dir string) (map[string][]constant, error) {
	fset := token.NewFileSet()
	files, err := goFiles(dir)
	if err != nil {
		return nil, err
	}
	named := map[string]bool{}
	var decls []*ast.GenDecl
	for _, f := range files {
		file, err := parser.ParseFile(fset, f, nil, 0)
		if err != nil {
			return nil, err
		}
		for _, d := range file.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok {
				continue
			}
			switch gd.Tok {
			case token.TYPE:
				for _, s := range gd.Specs {
					ts := s.(*ast.TypeSpec)
					if id, ok := ts.Type.(*ast.Ident); ok && ts.Name.IsExported() && ts.Assign == 0 && basic[id.Name] {
						named[ts.Name.Name] = true
					}
				}
			case token.CONST:
				decls = append(decls, gd)
			}
		}
	}
	out := map[string][]constant{}
	for _, gd := range decls {
		typ := ""
		for _, s := range gd.Specs {
			vs := s.(*ast.ValueSpec)
			if vs.Type != nil {
				typ = ""
				if id, ok := vs.Type.(*ast.Ident); ok {
					typ = id.Name
				}
			} else if len(vs.Values) > 0 {
				typ = "" // an untyped constant, or one typed by its value
			}
			if !named[typ] {
				continue
			}
			for _, n := range vs.Names {
				if n.IsExported() {
					out[typ] = append(out[typ], constant{n.Name})
				}
			}
		}
	}
	return out, nil
}

var basic = map[string]bool{"int": true, "int8": true, "int16": true, "int32": true, "int64": true, "uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true, "string": true}

// words splits a Go identifier into its CamelCase words, keeping an acronym
// whole: "TTestInd" is T Test Ind, "LBFGSB" is LBFGSB, "BinsSqrt" Bins Sqrt.
func words(s string) []string {
	var out []string
	r := []rune(s)
	start := 0
	for i := 1; i < len(r); i++ {
		lowerToUpper := unicode.IsUpper(r[i]) && (unicode.IsLower(r[i-1]) || unicode.IsDigit(r[i-1]))
		acronymEnd := unicode.IsUpper(r[i]) && unicode.IsUpper(r[i-1]) && i+1 < len(r) && unicode.IsLower(r[i+1])
		if lowerToUpper || acronymEnd {
			out = append(out, string(r[start:i]))
			start = i
		}
	}
	return append(out, string(r[start:]))
}

// snake is the Ruby spelling of a Go name: "TwoSided" is two_sided.
func snake(s string) string { return strings.ToLower(strings.Join(words(s), "_")) }

// commonPrefix is the run of whole words every name starts with, when that
// leaves something of each: CenterMedian and CenterMean share "Center".
func commonPrefix(names []string) string {
	if len(names) < 2 {
		return ""
	}
	first := words(names[0])
	prefix := ""
	for i := 0; i < len(first)-1; i++ {
		p := prefix + first[i]
		for _, n := range names[1:] {
			if !strings.HasPrefix(n, p) || len(n) == len(p) || !unicode.IsUpper([]rune(n[len(p):])[0]) && !unicode.IsDigit([]rune(n[len(p):])[0]) {
				return prefix
			}
		}
		prefix = p
	}
	return prefix
}
